const body = msg.payload || {};
msg.headers = { 'content-type': 'application/json' };
msg.payload = {
  topic: body.topic,
  mode: body.mode || 'auto',
  max_results: body.max_results || 10,
  no_network: body.no_network === undefined ? false : body.no_network,
  providers: body.providers || []
};
return msg;

const data = msg.payload || {};
msg.payload = {
  run_id: data.run_id,
  report_markdown: data.report_markdown,
  provider_health: data.provider_health || [],
  source_count: (data.sources || []).length,
  evidence_count: (data.evidence || []).length,
  claim_count: (data.claims || []).length
};
return msg;
